Custom hooks extract reusable logic from components. They start with `use` and can call other hooks.

```jsx
import { useState, useEffect } from 'react';

function useLocalStorage(key, initialValue) {
    const [value, setValue] = useState(() => {
        const stored = localStorage.getItem(key);
        return stored ? JSON.parse(stored) : initialValue;
    });

    useEffect(() => {
        localStorage.setItem(key, JSON.stringify(value));
    }, [key, value]);

    return [value, setValue];
}

// Usage — works like useState but persists!
function Settings() {
    const [theme, setTheme] = useLocalStorage('theme', 'dark');
    const [lang, setLang] = useLocalStorage('language', 'en');

    return (
        <div>
            <button onClick={() => setTheme(t => t === 'dark' ? 'light' : 'dark')}>
                Theme: {theme}
            </button>
        </div>
    );
}
```

Custom hooks let you share stateful logic between components without render props or HOCs. Common custom hooks: `useDebounce`, `useFetch`, `useMediaQuery`, `useOnClickOutside`, `usePrevious`.

**`useMemo`** — cache a computed value. Re-computes only when dependencies change.
```jsx
function FilteredList({ items, filter }) {
    const filtered = useMemo(() => {
        return items.filter(item =>
            item.name.toLowerCase().includes(filter.toLowerCase())
        );
    }, [items, filter]);  // Only recompute when items or filter change

    return filtered.map(item => <ListItem key={item.id} item={item} />);
}
```

**`useCallback`** — cache a function reference. Same function identity unless dependencies change.
```jsx
function Parent() {
    const handleClick = useCallback((id) => {
        deleteItem(id);
    }, []);  // Stable reference

    return <MemoizedChild onClick={handleClick} />;
}

const MemoizedChild = React.memo(({ onClick }) => {
    return <button onClick={() => onClick(1)}>Delete</button>;
});
```

**When to use:**
- `useMemo`: expensive calculations (filtering 10K items, complex transforms)
- `useCallback`: function passed to `React.memo` child (prevents re-renders)

**When NOT to use:** simple calculations, functions not passed to memoized children. Memoization has its own cost — don't optimize what isn't slow.

Always handle all three states — not just the happy path.

```jsx
function UserList() {
    const [users, setUsers] = useState(null);
    const [error, setError] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch('/api/users')
            .then(res => {
                if (!res.ok) throw new Error(`HTTP ${res.status}`);
                return res.json();
            })
            .then(data => setUsers(data))
            .catch(err => setError(err.message))
            .finally(() => setLoading(false));
    }, []);

    if (loading) return <Skeleton count={5} />;  // Skeleton > spinner
    if (error) return <ErrorBanner message={error} onRetry={() => window.location.reload()} />;
    if (users.length === 0) return <EmptyState message="No users yet" />;

    return (
        <ul>
            {users.map(u => <UserCard key={u.id} user={u} />)}
        </ul>
    );
}
```

**UX tips:**
- Use skeleton screens instead of spinners (feels faster)
- Error states should have a retry button
- Empty states should guide the user ("Create your first item")
- `null` initial state distinguishes "not loaded yet" from "loaded empty array"

React re-renders a component when its state changes or its parent re-renders. Here's how to prevent unnecessary ones:

**1. React.memo — skip re-render if props unchanged:**
```jsx
const ExpensiveChild = React.memo(({ data, onSelect }) => {
    return <div>{/* expensive rendering */}</div>;
});
```

**2. Stable references for props:**
```jsx
function Parent() {
    // BAD: new function every render → memo useless
    return <Child onClick={() => doSomething()} />;

    // GOOD: stable reference
    const handleClick = useCallback(() => doSomething(), []);
    return <Child onClick={handleClick} />;
}
```

**3. Move state down — only re-render what changes:**
```jsx
// BAD: typing re-renders ExpensiveComponent
function Page() {
    const [search, setSearch] = useState('');
    return <>
        <input value={search} onChange={e => setSearch(e.target.value)} />
        <ExpensiveComponent />
    </>;
}

// GOOD: extract search into its own component
function SearchInput() {
    const [search, setSearch] = useState('');
    return <input value={search} onChange={e => setSearch(e.target.value)} />;
}
function Page() {
    return <>
        <SearchInput />
        <ExpensiveComponent />  {/* No longer re-renders on typing */}
    </>;
}
```

**Rule:** profile before optimizing. React DevTools Profiler shows which components re-render and why.

Use CSS variables + React context for a clean dark mode implementation.

```css
/* styles.css */
:root {
    --bg: #ffffff;
    --text: #1a1a1a;
    --border: #e0e0e0;
}

[data-theme='dark'] {
    --bg: #0a0a0a;
    --text: #d8d8d8;
    --border: #2a2a2a;
}

body {
    background: var(--bg);
    color: var(--text);
    transition: background 0.2s, color 0.2s;
}
```

```jsx
const ThemeContext = createContext();

function ThemeProvider({ children }) {
    const [theme, setTheme] = useState(() => {
        return localStorage.getItem('theme') || 'dark';
    });

    useEffect(() => {
        document.documentElement.setAttribute('data-theme', theme);
        localStorage.setItem('theme', theme);
    }, [theme]);

    const toggle = () => setTheme(t => t === 'dark' ? 'light' : 'dark');

    return (
        <ThemeContext.Provider value={{ theme, toggle }}>
            {children}
        </ThemeContext.Provider>
    );
}

function ThemeToggle() {
    const { theme, toggle } = useContext(ThemeContext);
    return <button onClick={toggle}>{theme === 'dark' ? '☀️' : '🌙'}</button>;
}
```

CSS variables update instantly across the entire page. No prop drilling, no re-rendering every component. The `data-theme` attribute on `<html>` controls everything via CSS.
